package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.submissionfeedback.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class SubmissionFeedbackStoreIntegrationTest {
 SubmissionStoreIntegrationTest f;SubmissionFeedbackStore store;SubmissionStore.Submission answer;
 @BeforeEach void setup(){f=new SubmissionStoreIntegrationTest();f.setup();f.open();answer=f.submit(f.f.key(),0,2,"Original answer").submission();store=new SubmissionFeedbackStore(f.f.source,f.parent.store,f.store,Clock.systemUTC());}
 SubmissionFeedbackStore.Feedback change(long version,long reviewed,String content){return store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,version,new SubmissionFeedbackInput(content,reviewed,2),f.f.trace);}
 SubmissionFeedbackStore.View get(UUID actor,boolean owner){return store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),actor,owner);}
 SubmissionFeedbackStore.History history(long before,int limit){return store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false,before,limit);}
 void status(int code,org.junit.jupiter.api.function.Executable action){f.status(code,action);}
 @Test void absentFeedbackHasNoPersistentIdAuditOrEvent(){assertNull(get(f.author,false).feedback());assertFalse(get(f.author,false).canWrite());assertTrue(get(f.f.owner,true).canWrite());assertEquals(1,get(f.author,false).submissionVersion());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_feedback WHERE submission_id=?",Integer.class,answer.submissionId()));}
 @Test void fullFeedbackAuditAndProtobufPinTheImmutableAnswer()throws Exception{
  var v=change(0,1,"Feedback <script>\n의견");assertEquals(7,v.feedbackId().version());assertEquals(f.author,v.authorId());assertEquals(f.f.owner,v.reviewerId());assertEquals(1,v.submissionVersion());assertEquals(2,v.assignmentVersion());assertEquals("AUTHOR_AND_OWNER",v.audience());assertEquals(v,get(f.author,false).feedback());assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());
  var e=SubmissionFeedbackEnvelopeV1.parseFrom(f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.feedbackId()));var p=SubmissionFeedbackSnapshotV1.parseFrom(e.getPayload());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.f.owner.toString(),e.getActorId());assertEquals("SubmissionFeedback",e.getAggregateType());assertEquals(v.content(),p.getContent());assertEquals(answer.submissionId().toString(),p.getSubmissionId());assertEquals(1,p.getSubmissionVersion());assertEquals("AUTHOR_AND_OWNER",p.getAudience());assertEquals(answer,f.store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false));assertEquals(1,f.events(answer.submissionId()));
 }
 @Test void feedbackHasIndependentVersionAndStableNoOp(){var first=change(0,1,"First");assertEquals(first,change(1,1,"First"));status(412,()->change(0,1,"First"));var corrected=change(1,1,"Corrected");assertEquals(first.feedbackId(),corrected.feedbackId());assertEquals(first.createdAt(),corrected.createdAt());assertEquals(2,corrected.version());assertEquals(1,get(f.author,false).submissionVersion());assertEquals(2,f.events(first.feedbackId()));}
 @Test void newAnswerDoesNotAutomaticallyChangeFeedbackAndOldReviewCannotSave(){var first=change(0,1,"Check this part");var second=f.submit(f.f.key(),1,2,"Revised answer").submission();assertEquals(first,get(f.author,false).feedback());assertEquals(2,get(f.author,false).submissionVersion());status(409,()->change(1,1,"Old review"));var next=change(1,2,"Check this part");assertEquals(first.feedbackId(),next.feedbackId());assertEquals(2,next.submissionVersion());assertEquals(2,next.version());assertEquals(1,history(2,5).items().getFirst().snapshot().submissionVersion());assertEquals(second,f.store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false));}
 @Test void reviewUsesSubmittedInstructionVersionAfterAssignmentEdits(){f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"Changed instructions","New description",f.f.trace);var v=change(0,1,"Feedback on original instructions");assertEquals(2,v.assignmentVersion());status(409,()->store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,1,new SubmissionFeedbackInput("Wrong instructions",1,3),f.f.trace));assertEquals(3,f.parent.store.get(f.group,f.space,f.study,f.assignment).version());}
 @Test void closedAssignmentsAcceptFeedbackButArchivedParentsAreReadOnly(){f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);assertTrue(get(f.f.owner,true).canWrite());var v=change(0,1,"Review after close");f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,3,"RETIRED",f.f.trace);assertFalse(get(f.f.owner,true).canWrite());assertEquals(v,get(f.author,false).feedback());status(409,()->change(1,1,"Review after close"));assertEquals(1,history(Long.MAX_VALUE,5).items().size());}
 @Test void retiredStudyFreezesFeedbackWithoutHidingPriorAudit(){var v=change(0,1,"Before archive");f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,1,"RETIRED",f.f.trace);assertFalse(get(f.f.owner,true).canWrite());status(409,()->change(1,1,"After archive"));assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());}
 @Test void peerAndWrongParentReferencesCannotReadCurrentOrHistory(){change(0,1,"Private feedback");var peer=f.f.ids.next();status(404,()->get(peer,false));status(404,()->store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),peer,false,Long.MAX_VALUE,5));status(404,()->store.get(f.f.ids.next(),f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.f.ids.next(),f.study,f.assignment,answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.space,f.study,f.f.ids.next(),answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.space,f.study,f.assignment,f.f.ids.next(),f.f.owner,true));}
 @Test void historyUsesIndependentDescendingFeedbackCursor(){for(int n=0;n<7;n++)change(n,1,"Comment "+n);var first=history(Long.MAX_VALUE,5);assertEquals(List.of(7L,6L,5L,4L,3L),first.items().stream().map(SubmissionFeedbackStore.Revision::version).toList());assertEquals(3L,first.nextBefore());var second=history(first.nextBefore(),5);assertEquals(List.of(2L,1L),second.items().stream().map(SubmissionFeedbackStore.Revision::version).toList());assertNull(second.nextBefore());}
 @Test void concurrentInitialAndExistingCommentsHaveExactlyOneWinner()throws Exception{
  try(var executor=Executors.newVirtualThreadPerTaskExecutor()){for(int round=0;round<2;round++){long expected=round;var tasks=new ArrayList<Future<Boolean>>();var barrier=new CyclicBarrier(2);for(int n=0;n<2;n++){String text="Round "+round+" / "+n;tasks.add(executor.submit(()->{barrier.await();try{change(expected,1,text);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));}assertNotEquals(tasks.get(0).get(20,TimeUnit.SECONDS),tasks.get(1).get(20,TimeUnit.SECONDS));assertEquals(round+1,get(f.author,false).feedback().version());}}
 }
 @Test void simultaneousResubmissionNeverAttachesOldReviewToNewAnswer()throws Exception{
  try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var submission=executor.submit(()->{barrier.await();return f.submit(f.f.key(),1,2,"Concurrent answer").submission();});var feedback=executor.submit(()->{barrier.await();try{return change(0,1,"Reviewed original");}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals(2,submission.get(20,TimeUnit.SECONDS).version());var reviewed=feedback.get(20,TimeUnit.SECONDS);if(reviewed!=null)assertEquals(1,reviewed.submissionVersion());assertEquals(reviewed,get(f.author,false).feedback());}
 }
 @Test void outboxFailureRollsBackInitialAndCorrectedFeedbackAudit(){String constraint="feedback_fail_"+answer.submissionId().toString().replace("-","");String check=" CHECK(aggregatetype<>'submission-feedback' OR trace_id<>'"+f.f.trace+"') NOT VALID";f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+check);try{assertThrows(RuntimeException.class,()->change(0,1,"Fail initial"));assertNull(get(f.author,false).feedback());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}var saved=change(0,1,"Saved");f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+check);try{assertThrows(RuntimeException.class,()->change(1,1,"Fail correction"));assertEquals(saved,get(f.author,false).feedback());assertEquals(1,history(Long.MAX_VALUE,5).items().size());assertEquals(1,f.events(saved.feedbackId()));}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}}
 @Test void databaseRejectsMissingReviewedRevisionAndDuplicateFeedback(){var v=change(0,1,"Validated provenance");assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE submission_feedback SET submission_version=999999 WHERE feedback_id=?",v.feedbackId()));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("INSERT INTO submission_feedback SELECT ?,submission_id,assignment_id,study_id,group_id,space_id,author_id,version,submission_version,snapshot FROM submission_feedback WHERE feedback_id=?",f.f.ids.next(),v.feedbackId()));assertEquals(v,get(f.author,false).feedback());}
}
